from typing import List
def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove all spaces from the input
    s = paren_string.replace(" ", "")

    groups = []
    current = []
    balance = 0

    for ch in s:
        if ch == '(' or ch == ')':
            current.append(ch)
            if ch == '(':
                balance += 1
            else:
                balance -= 1

            # If balance returns to zero, we have completed a group
            if balance == 0 and current:
                groups.append(''.join(current))
                current = []

    # In case of any leftover characters (shouldn't happen with valid input)
    if current:
        groups.append(''.join(current))

    return groups

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    for i in range(n // 2, 0, -1):
        if n % i == 0:
            return i
    return 1  # fallback for n = 1 (though not expected)

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    flipped = ""
    for char in string:
        if char.islower():
            flipped += char.upper()
        elif char.isupper():
            flipped += char.lower()
        else:
            flipped += char
    return flipped

import math
def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])
def find_zero(xs: list):
    """
    xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    def p(x: float) -> float:
        return poly(xs, x)

    if p(0) == 0:
        return 0.0

    low, high = -1.0, 1.0
    while p(low) * p(high) > 0:
        low *= 2.0
        high *= 2.0

    if p(low) == 0:
        return low
    if p(high) == 0:
        return high

    for _ in range(200):
        mid = (low + high) / 2.0
        if p(mid) == 0:
            return mid
        if p(low) * p(mid) < 0:
            high = mid
        else:
            low = mid

    return (low + high) / 2.0

