def fib4(n: int):
    if n < 0:
        return 0
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    a, b, c, d = 0, 0, 2, 0  # fib4(0), fib4(1), fib4(2), fib4(3)
    for _ in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

def median(l: list):
    sorted_l = sorted(l)
    n = len(sorted_l)
    if n == 0:
        return None
    if n % 2 == 1:
        return sorted_l[n // 2]
    else:
        mid = n // 2
        return (sorted_l[mid - 1] + sorted_l[mid]) / 2

def smallest_change(arr):
    changes = 0
    left = 0
    right = len(arr) - 1

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

