def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [p for p in range(2, a + 1) if is_prime(p)]

    for i in primes:
        for j in primes:
            for k in primes:
                if i * j * k == a:
                    return True

    return False

def is_simple_power(x, n):
    # Special case: n = 1, then 1**k = 1 for any k, so only x == 1 is true
    if n == 1:
        return x == 1

    power = 1  # n**0
    while power <= x:
        if power == x:
            return True
        power *= n
    return False

def hex_key(num):
    """Counts the number of hexadecimal digits that are prime numbers."""
    prime_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for char in num:
        if char in prime_digits:
            count += 1
    return count

def starts_one_ends(n):
