        return 1
    return 18 * (10 ** (n - 2))

def add(lst):
    """
    Given a non-empty list of integers lst. add the even elements that are at odd indices.
    """
    total = 0
    for i in range(len(lst)):
        if i % 2 == 1 and lst[i] % 2 == 0:
            total += lst[i]
    return total

def get_row(lst, x):
    result = []
    for row_idx, row in enumerate(lst):
        cols = [col_idx for col_idx, val in enumerate(row) if val == x]
        cols.sort(reverse=True)
        for col_idx in cols:
            result.append((row_idx, col_idx))
    return result

def sort_array(array):
    if not array:
        return []

    first_value = array[0]
    last_value = array[-1]

    if (first_value + last_value) % 2 == 1:
        return sorted(array)
    else:
        return sorted(array, reverse=True)

def any_int(x, y, z):
    # Helper to check if a number is an integer (int or float with integer value)
    def is_integer(n):
        if isinstance(n, bool):
            return False
        if isinstance(n, int):
            return True
        if isinstance(n, float):
            return n.is_integer()
        return False

    # All numbers must be integers
    if not (is_integer(x) and is_integer(y) and is_integer(z)):
        return False

    # Check if any number equals the sum of the other two
    return (x == y + z) or (y == x + z) or (z == x + y)

def skjkasdkd(lst):
    def is_prime(n):
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        if n % 3 == 0:
            return n == 3
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    largest_prime = None

    for num in lst:
        if num > 1 and is_prime(num):
            if largest_prime is None or num > largest_prime:
                largest_prime = num

    if largest_prime is None:
        return 0

    return sum(int(digit) for digit in str(largest_prime))

