def rounded_avg(n, m):
    if n > m:
        return -1
    avg = (n + m) / 2
    rounded = round(avg)
    return bin(rounded)

def f(n):
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            factorial = 1
            for j in range(2, i + 1):
                factorial *= j
            result.append(factorial)
        else:
            result.append(sum(range(1, i + 1)))
    return result

