def histogram(test):
    if not test:
        return {}
    words = test.split()
    counts = {}
    for word in words:
        if word:
            counts[word] = counts.get(word, 0) + 1
    if not counts:
        return {}
    max_count = max(counts.values())
    return {k: v for k, v in counts.items() if v == max_count}

def reverse_delete(s, c):
    chars_to_delete = set(c)
    result = ''.join(ch for ch in s if ch not in chars_to_delete)
    return (result, result == result[::-1])

def max_fill(grid, capacity):
    lowerings = 0
    for well in grid:
        water = sum(well)
        lowerings += (water + capacity - 1) // capacity
    return lowerings

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for ch in s:
            if ch == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    s1, s2 = lst[0], lst[1]
    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'
