import re
def valid_date(date):
    if not isinstance(date, str):
        return False
    if not re.fullmatch(r"\d{2}-\d{2}-\d{4}", date):
        return False

    month, day, year = map(int, date.split("-"))

    if month < 1 or month > 12:
        return False
    if day < 1:
        return False

    if month in {1, 3, 5, 7, 8, 10, 12}:
        max_day = 31
    elif month in {4, 6, 9, 11}:
        max_day = 30
    else:
        max_day = 29

    return day <= max_day

def split_words(txt):
    if any(ch.isspace() for ch in txt):
        return txt.split()
    if "," in txt:
        return txt.split(",")
    return sum(1 for ch in txt if ch.islower() and (ord(ch) - ord('a')) % 2 == 1)

def is_sorted(lst):
    # Check if list is sorted in ascending order
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False

    # Check duplicate rule: no number may appear more than twice
    counts = {}
    for num in lst:
        counts[num] = counts.get(num, 0) + 1
        if counts[num] > 2:
            return False

    return True

def intersection(interval1, interval2):
    # Helper function to check if a number is prime
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])

    if start > end:
        return "NO"

    length = end - start
    if is_prime(length):
        return "YES"
    else:
        return "NO"

def prod_signs(arr):
    if not arr:
        return None

    product_sign = 1
    sum_abs = 0

    for num in arr:
        if num > 0:
            product_sign *= 1
        elif num < 0:
            product_sign *= -1
        else:
            product_sign *= 0
        sum_abs += abs(num)

    return sum_abs * product_sign

def minPath(grid, k):
    n = len(grid)

    start = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start = (i, j)
                break
        if start is not None:
            break

    path = [1]
    cur = start
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for _ in range(k - 1):
        best_val = float("inf")
        best_pos = None

        for di, dj in directions:
            ni, nj = cur[0] + di, cur[1] + dj
            if 0 <= ni < n and 0 <= nj < n:
                val = grid[ni][nj]
                if val < best_val:
                    best_val = val
                    best_pos = (ni, nj)

        cur = best_pos
        path.append(best_val)

    return path

def tri(n):
    memo = {0: 1, 1: 3}

    def value(k):
        if k in memo:
            return memo[k]
        if k % 2 == 0:
            memo[k] = 1 + k // 2
        else:
            memo[k] = value(k - 1) + value(k - 2) + value(k + 1)
        return memo[k]

    return [value(i) for i in range(n + 1)]

def is_nested(string):
    for j in range(len(string)):
        if string[j] == '[':
            opens_before = string[:j].count('[')
            closes_after = string[j + 1:].count(']')
            if opens_before > 0 and closes_after >= 2:
                return True
    return False

def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False

    last_char = txt[-1]
    if not last_char.isalpha():
        return False

    # If there is a character before the last one and it is not a space,
    # then the last character is part of a word.
    if len(txt) > 1 and txt[-2] != ' ':
