def largest_smallest_integers(lst):
    negatives = [x for x in lst if x < 0]
    positives = [x for x in lst if x > 0]
    a = max(negatives) if negatives else None
    b = min(positives) if positives else None
    return (a, b)

def compare_one(a, b):
    def to_float(x):
        if isinstance(x, str):
            return float(x.replace(',', '.'))
        return float(x)
    fa = to_float(a)
    fb = to_float(b)
    if fa == fb:
        return None
    return a if fa > fb else b

def fix_spaces(text):
    result = []
    i = 0
    while i < len(text):
        if text[i] == ' ':
            j = i
            while j < len(text) and text[j] == ' ':
                j += 1
            count = j - i
            if count > 2:
                result.append('-')
            else:
                result.append('_' * count)
            i = j
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

def file_name_check(file_name):
    # Condition: exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    before, after = file_name.split('.')

    # Condition: before dot should not be empty and start with a letter
    if not before or not before[0].isalpha():
        return 'No'

    # Condition: after dot should be one of the allowed extensions
    if after not in ['txt', 'exe', 'dll']:
        return 'No'

    # Condition: no more than three digits
    if sum(c.isdigit() for c in file_name) > 3:
        return 'No'

    # All conditions satisfied
    return 'Yes'

def sum_squares(lst):
    total = 0
    for i, x in enumerate(lst):
        if i % 3 == 0:
            total += x ** 2
        elif i % 4 == 0:
            total += x ** 3
        else:
            total += x
    return total

def specialFilter(nums):
    count = 0
    for num in nums:
        if num > 10:
            s = str(num)
            first_digit = int(s[0])
            last_digit = int(s[-1])
            if first_digit % 2 == 1 and last_digit % 2 == 1:
                count += 1
    return count

def get_max_triples(n: int) -> int:
    def comb3(x: int) -> int:
        if x < 3:
            return 0
        return x * (x - 1) * (x - 2) // 6

    zeros = (n + 1) // 3
    ones = n - zeros

    return comb3(ones) + comb3(zeros)

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    return x if is_prime(n) else y

def compare(game, guess):
    """Return a list of absolute differences between game scores and guesses."""
    return [abs(g - guess_i) for g, guess_i in zip(game, guess)]

def cycpattern_check(a, b):
    """
    You are given 2 words. You need to return True if the second word or any of its rotations is a substring in the first word.
    """
    n = len(b)
    for i in range(n):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True
    return False

def find_max(words):
    if not words:
        return ""
    return min(words, key=lambda w: (-len(set(w)), w))

def do_algebra(operator, operand):
    expr = str(operand[0])
    for i, op in enumerate(operator):
        expr += op + str(operand[i + 1])
    return eval(expr)

def solve(s):
    if not any(c.isalpha() for c in s):
        return s[::-1]
    return ''.join(c.swapcase() if c.isalpha() else c for c in s)

import hashlib
def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == "":
        return None
    return hashlib.md5(text.encode()).hexdigest()
